import json

slug = (params.get("practice_slug") or "").strip()
problem = ""
settings = {}
state = {"handled_slot_keys": []}
freed_notes = []

def read_json(path):
    try:
        raw = api.files.read(file=path, scope="org")
    except Exception as exc:
        return None, "Couldn't read " + path + ": " + str(exc)
    try:
        return json.loads(raw), None
    except Exception as exc:
        return None, path + " isn't valid JSON (" + str(exc) + ")"

# No slug set (the param ships blank and can't be edited in the app): use
# the practice settings file, as long as there's exactly one.
if not slug:
    try:
        practice_entries = api.files.list(path="PracticeManager/Practices", scope="org") or []
    except Exception:
        practice_entries = []
    practice_slugs = []
    for e in practice_entries:
        name = str((e.get("name") if isinstance(e, dict) else e) or "").split("/")[-1]
        if name.endswith(".json"):
            practice_slugs.append(name[: -len(".json")])
    if len(practice_slugs) == 1:
        slug = practice_slugs[0]

if not slug:
    problem = "No practice_slug configured for this automation, and there isn't exactly one practice settings file in PracticeManager/Practices to fall back on."
else:
    found, err = read_json("PracticeManager/Practices/" + slug + ".json")
    if found is None:
        problem = err or ("No practice settings file found for slug '" + slug
                           + "'. Run Healthcare Practice Management: Start practice setup first.")
    else:
        settings = found
        state_data, _ = read_json("PracticeManager/State/" + slug + "-gap-filler.json")
        state = state_data or {"handled_slot_keys": []}
        # Written by "Apply patient's chosen reschedule time" whenever it moves
        # a booking -- Cliniko doesn't mark a moved booking cancelled, so the
        # old time it frees can't be found by checking Cliniko alone.
        notes, _ = read_json("PracticeManager/State/" + slug + "-freed-slots.json")
        freed_notes = notes if isinstance(notes, list) else []

import datetime

def cliniko(tool, args):
    return api.connectors.invoke(server="cliniko-scheduling", tool=tool, args=args) or {}

def link_id(obj, key):
    link = ((obj.get(key) or {}).get("links") or {}).get("self") or ""
    return link.rstrip("/").split("/")[-1] if link else ""

def parse(iso_str):
    return datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

settings = params["settings"] or {}
state = params["state"] or {}
freed_notes = params.get("freed_notes") or []

# Only slots someone could realistically take: at least 2 hours away (time for
# the manager to approve and a patient to reply and travel) and no more than 7
# days out (further-out gaps usually refill through normal booking). A practice
# can override either via "gap_filler" in its settings file.
gap = settings.get("gap_filler") or {}
min_notice_hours = gap.get("min_notice_hours", 2)
max_days_ahead = gap.get("max_days_ahead", 7)
now = datetime.datetime.now(datetime.timezone.utc)
window_start = now + datetime.timedelta(hours=min_notice_hours)
window_end = now + datetime.timedelta(days=max_days_ahead)

handled = [k for k in (state.get("handled_slot_keys") or []) if k]
handled_set = set(handled)

found = []
bookings_checked = 0
cancelled_in_window = 0

# 1. Cancelled bookings. Cliniko leaves cancelled appointments OUT of
# /individual_appointments unless a cancelled_at filter uses the "*" (any
# value) operator, so ask for them explicitly. Every run re-reads the whole
# window rather than only "since last check" --
# a slot cancelled weeks ago gets picked up the day it enters the window, and
# handled_slot_keys stops the same slot being raised twice once its WorkQ
# item exists.
page = 1
while page <= 5:
    res = cliniko("list_individual_appointments", {
        "q": ["starts_at:>=" + zulu(window_start), "starts_at:<=" + zulu(window_end), "cancelled_at:*"],
        "sort": "starts_at:asc", "per_page": 100, "page": page,
    })
    appts = res.get("individual_appointments") or []
    bookings_checked += len(appts)
    for a in appts:
        if not a.get("cancelled_at") or a.get("archived_at") or a.get("deleted_at"):
            continue
        cancelled_in_window += 1
        found.append({
            "key": "cancelled:" + str(a.get("id") or ""),
            "source": "cancelled",
            "appointment_id": str(a.get("id") or ""),
            "patient_id": link_id(a, "patient"),
            "starts_at": a.get("starts_at") or "",
            "ends_at": a.get("ends_at") or "",
            "practitioner_id": link_id(a, "practitioner"),
            "business_id": link_id(a, "business"),
            "appointment_type_id": link_id(a, "appointment_type"),
        })
    if len(appts) < 100:
        break
    page += 1

# 2. Times freed by "Apply patient's chosen reschedule time" moving a booking.
for n in freed_notes:
    if not isinstance(n, dict) or not n.get("starts_at"):
        continue
    note_start = str(n.get("starts_at") or "")
    found.append({
        "key": "moved:" + str(n.get("appointment_id") or "") + ":" + note_start,
        "source": "moved",
        "appointment_id": str(n.get("appointment_id") or ""),
        "patient_id": n.get("patient_id") or "",
        "starts_at": note_start,
        "ends_at": n.get("ends_at") or "",
        "practitioner_id": n.get("practitioner_id") or "",
        "business_id": n.get("business_id") or "",
        "appointment_type_id": n.get("appointment_type_id") or "",
    })

slots = []
for s in found:
    if len(slots) >= 10:
        break  # the rest wait for the next run rather than being dropped
    if s["key"] in handled_set or not s["practitioner_id"]:
        continue
    try:
        start = parse(s["starts_at"])
        end = parse(s["ends_at"]) if s["ends_at"] else start + datetime.timedelta(minutes=30)
    except Exception:
        continue
    if start < window_start:
        # Too close (or already past) to fill -- never worth raising later either.
        handled.append(s["key"])
        handled_set.add(s["key"])
        continue
    if start > window_end:
        continue  # not in the window yet; picked up on a later run
    # Still free? Someone may already have been booked into it (front desk, or
    # the reschedule desk moving another patient there).
    taken = False
    nearby = (cliniko("list_individual_appointments", {
        "q": ["starts_at:>=" + zulu(start - datetime.timedelta(hours=4)), "starts_at:<" + zulu(end),
              "practitioner_id:=" + s["practitioner_id"]],
        "per_page": 100,
    }).get("individual_appointments") or [])
    for other in nearby:
        if other.get("cancelled_at") or other.get("archived_at") or other.get("deleted_at"):
            continue
        if link_id(other, "practitioner") != s["practitioner_id"]:
            continue
        try:
            o_start = parse(other.get("starts_at") or "")
            o_end = parse(other.get("ends_at") or "")
        except Exception:
            continue
        if o_start < end and o_end > start:
            taken = True
            break
    handled_set.add(s["key"])  # don't look at it twice in this run
    if taken:
        handled.append(s["key"])
    else:
        # Marked handled by "Rank candidates, draft offers and create the
        # WorkQ item" only once its item exists, so a run that fails before
        # then retries the slot next time instead of losing it.
        slots.append(s)

handled_slot_keys = handled[-1000:]
summary = ("Checked " + str(bookings_checked) + " bookings between " + zulu(window_start) + " and " + zulu(window_end)
           + "; " + str(cancelled_in_window) + " cancelled, " + str(len(freed_notes)) + " moved-booking notes, "
           + str(len(slots)) + " slot(s) still free and newly raised.")

import json
import datetime

def cliniko(server, tool, args):
    return api.connectors.invoke(server=server, tool=tool, args=args) or {}

def link_id(obj, key):
    link = ((obj.get(key) or {}).get("links") or {}).get("self") or ""
    return link.rstrip("/").split("/")[-1] if link else ""

def parse(iso_str):
    return datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def is_live(a):
    return not a.get("cancelled_at") and not a.get("archived_at") and not a.get("deleted_at")

def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True), scope="org")

slug = params["slug"]
settings = params["settings"] or {}
tz_name = settings.get("timezone") or "UTC"

def format_local(iso_str, fmt="%a %d %b, %I:%M %p"):
    try:
        from zoneinfo import ZoneInfo
        return parse(iso_str).astimezone(ZoneInfo(tz_name)).strftime(fmt).replace(" 0", " ")
    except Exception:
        return iso_str

slot = {
    "key": params["key"], "source": params["source"], "appointment_id": params["appointment_id"],
    "patient_id": params.get("patient_id") or "", "starts_at": params["starts_at"],
    "ends_at": params.get("ends_at") or "", "practitioner_id": params["practitioner_id"],
    "business_id": params.get("business_id") or "", "appointment_type_id": params.get("appointment_type_id") or "",
}
practitioner_id = slot["practitioner_id"]
slot_start = parse(slot["starts_at"])
slot_end = parse(slot["ends_at"]) if slot["ends_at"] else slot_start + datetime.timedelta(minutes=30)
now = datetime.datetime.now(datetime.timezone.utc)

type_name = ""
if slot["appointment_type_id"]:
    try:
        type_name = (cliniko("cliniko-scheduling", "get_appointment_type", {"id": slot["appointment_type_id"]}) or {}).get("name") or ""
    except Exception:
        type_name = ""

def practitioner_appts(q_from, q_to, pages):
    out = []
    page = 1
    while page <= pages:
        q = ["starts_at:>=" + zulu(q_from), "practitioner_id:=" + practitioner_id]
        if q_to:
            q.append("starts_at:<" + zulu(q_to))
        rows = (cliniko("cliniko-scheduling", "list_individual_appointments",
                        {"q": q, "sort": "starts_at:asc", "per_page": 100, "page": page}).get("individual_appointments") or [])
        out.extend(a for a in rows if is_live(a) and link_id(a, "practitioner") == practitioner_id)
        if len(rows) < 100:
            break
        page += 1
    return out

# Candidate 1: patients already booked later with the same practitioner (next
# 4 weeks) who might like to come in sooner. Same appointment type first.
upcoming = practitioner_appts(slot_end, now + datetime.timedelta(days=28), 3)
later = []
seen = set([slot["patient_id"]]) if slot["patient_id"] else set()
for same_type_pass in (True, False):
    for a in upcoming:
        pid = link_id(a, "patient")
        if not pid or pid in seen:
            continue
        if same_type_pass and slot["appointment_type_id"] and link_id(a, "appointment_type") != slot["appointment_type_id"]:
            continue
        seen.add(pid)
        later.append({"patient_id": pid, "appointment_id": str(a.get("id") or ""), "current_starts_at": a.get("starts_at") or "",
                      "same_type": link_id(a, "appointment_type") == slot["appointment_type_id"]})
        if len(later) >= 5:
            break
    if len(later) >= 5:
        break

# Candidate 2: overdue patients -- last seen by this practitioner 6-16 weeks
# ago with nothing booked since. A stand-in for recalls, which Cliniko's API
# doesn't expose; there's no practice waitlist to read from yet either.
overdue = []
recent_cutoff = now - datetime.timedelta(weeks=6)
past = practitioner_appts(now - datetime.timedelta(weeks=16), recent_cutoff, 3)
since = practitioner_appts(recent_cutoff, None, 5)
active = set(link_id(a, "patient") for a in since) | seen
last_visit = {}
for a in past:
    pid = link_id(a, "patient")
    if pid and pid not in active:
        last_visit[pid] = a.get("starts_at") or ""
for pid, visited in sorted(last_visit.items(), key=lambda kv: kv[1]):
    overdue.append({"patient_id": pid, "last_visit_at": visited})
    if len(overdue) >= 5:
        break

def patient_details(pid):
    try:
        p = cliniko("cliniko-patients", "get_patient", {"id": pid}) or {}
    except Exception:
        p = {}
    name = ((p.get("first_name") or "") + " " + (p.get("last_name") or "")).strip()
    return name or ("Patient " + pid), (p.get("email") or "").strip()

for c in later + overdue:
    c["name"], c["email"] = patient_details(c["patient_id"])

slot_label = format_local(slot["starts_at"])
end_label = format_local(zulu(slot_end), "%I:%M %p")
title = ("Freed slot: " + slot_label + (" (" + type_name + ")" if type_name else ""))[:200]

# One numbered list across both kinds -- the approval form refers to these
# numbers, and the offer step reads them back from the saved slot file.
candidates = []
for c in later:
    candidates.append({
        "n": len(candidates) + 1, "kind": "later", "patient_id": str(c["patient_id"]),
        "name": str(c["name"]), "email": str(c["email"]),
        "appointment_id": str(c["appointment_id"]), "current_starts_at": str(c["current_starts_at"]),
        "current_label": format_local(str(c["current_starts_at"])), "same_type": bool(c["same_type"]),
        "last_visit_label": "",
    })
for c in overdue:
    candidates.append({
        "n": len(candidates) + 1, "kind": "overdue", "patient_id": str(c["patient_id"]),
        "name": str(c["name"]), "email": str(c["email"]),
        "appointment_id": "", "current_starts_at": "", "current_label": "", "same_type": False,
        "last_visit_label": format_local(str(c["last_visit_at"]), "%d %b %Y").lstrip("0"),
    })

import json
import datetime

def parse(iso_str):
    return datetime.datetime.fromisoformat(iso_str.replace("Z", "+00:00"))

def zulu(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True), scope="org")

slug = params["slug"]
settings = params["settings"] or {}
policy = settings.get("policy") or {}
tone = str(policy.get("tone") or "warm, concise, no jargon")
practice_name = str(settings.get("name") or "")
tz_name = str(settings.get("timezone") or "UTC")
slot = params["slot"] or {}
slot_label = str(params["slot_label"] or "")
end_label = str(params["end_label"] or "")
type_name = str(params.get("type_name") or "")
title = str(params["title"] or "")[:200]
candidates = [c for c in (params.get("candidates") or []) if isinstance(c, dict)]
now = datetime.datetime.now(datetime.timezone.utc)

# Skip if an open item for this exact slot already exists (overlapping manual +
# scheduled runs), same guard as the reschedule desk. Checked before any AI
# call so a duplicate run costs nothing.
already_open = False
try:
    for row in api.workq.list(search=title) or []:
        if (row.get("title") == title and row.get("status") not in ("done", "cancelled")
                and "gap-filler" in (row.get("labels") or [])):
            already_open = True
            break
except Exception:
    already_open = False

def clean_json(raw):
    cleaned = str(raw or "").strip().strip("`").strip()
    if cleaned.lower().startswith("json"):
        cleaned = cleaned[4:]
    return json.loads(cleaned.strip())

def fallback_offer(c):
    greeting = "Hi " + (str(c.get("name") or "").split(" ")[0] or "there") + ",\n\n"
    if c.get("kind") == "later":
        body = ("An earlier appointment has just opened up on " + slot_label
                + ". You're currently booked for " + str(c.get("current_label") or "a later time")
                + " - would you like to move to the earlier time instead?")
    else:
        body = ("An appointment has just opened up on " + slot_label
                + ". It's been a little while since your last visit - would you like to book in?")
    return (greeting + body + "\n\nJust reply YES to this email and the first person to reply gets the spot.\n\n"
            + (practice_name or "Kind regards"))

todo_id = ""
if not already_open:
    # Step 3: AI ranks who to offer first and drafts each personalised offer.
    # Only patients with an email on file can be offered by email. Falls back
    # to the list order and a plain template if the AI call or its JSON fails,
    # so a bad response never stops the slot being raised.
    offerable = [c for c in candidates if c.get("email")]
    ranked = {}
    ai_problem = ""
    if offerable:
        listing = "\n".join(
            str(c["n"]) + ". " + str(c.get("name") or "") + " - "
            + ("currently booked " + str(c.get("current_label") or "") + ("" if c.get("same_type") else " (different appointment type)")
               if c.get("kind") == "later" else "last visit " + str(c.get("last_visit_label") or "") + ", nothing booked")
            for c in offerable
        )
        prompt = (
            "An allied-health practice" + (" called \"" + practice_name + "\"" if practice_name else "")
            + " has a free appointment slot on " + slot_label + " to " + end_label + " (practice timezone " + tz_name + ")"
            + (" for a " + type_name if type_name else "") + ". These patients could take it:\n" + listing + "\n\n"
            "Rank them by how likely they are to want it and how much it helps the practice: someone already booked later "
            "for the same appointment type moving earlier is the best fit; an overdue patient is next. Mark at most 3 as "
            "recommended. For EVERY patient, draft a short " + tone + " plain-text email offering them this slot. For a "
            "patient already booked, offer to move their existing booking earlier (name their current time). For an overdue "
            "patient, offer to book them in. Say the first person to reply YES gets it. Use real line breaks: greeting line, "
            "blank line, body, blank line, sign-off" + (" with the practice name" if practice_name else " without naming the practice")
            + ". Never give clinical advice and never invent details.\n\n"
            'Reply with ONLY JSON, no markdown: {"ranked": [{"n": <number>, "recommended": true|false, '
            '"reason": "<one short sentence>", "offer": "<email body>"}]}'
        )
        try:
            result = clean_json(api.ai.generate(prompt=prompt)) or {}
            for r in result.get("ranked") or []:
                if isinstance(r, dict) and isinstance(r.get("n"), int):
                    ranked[r["n"]] = r
        except Exception as exc:
            ai_problem = str(exc)

    order = [r_n for r_n in ranked if any(c["n"] == r_n for c in offerable)]
    order += [c["n"] for c in offerable if c["n"] not in order]
    by_n = {c["n"]: c for c in candidates}
    offers = []
    for rank, n in enumerate(order, start=1):
        c = by_n[n]
        r = ranked.get(n) or {}
        offers.append({
            **c,
            "rank": rank,
            "recommended": bool(r.get("recommended")) if ranked else rank <= 3,
            "reason": str(r.get("reason") or ""),
            "offer_text": str(r.get("offer") or "").strip() or fallback_offer(c),
        })

    def candidate_line(c):
        what = ("booked " + str(c.get("current_label") or "") + ("" if c.get("same_type") else " (different appointment type)")
                if c.get("kind") == "later" else "overdue, last visit " + str(c.get("last_visit_label") or ""))
        return str(c["n"]) + ". **" + str(c.get("name") or "") + "** - " + what

    lines = []
    for c in offers:
        lines.append(candidate_line(c) + (" - ⭐ recommended" if c["recommended"] else "")
                     + ("\n   _" + str(c["reason"]) + "_" if c["reason"] else ""))
    for c in candidates:
        if not c.get("email"):
            lines.append(candidate_line(c) + " - no email on file, can't be offered")
    candidate_block = "\n".join(lines) or "No candidates found: nobody is booked later with this practitioner in the next 4 weeks, and no overdue patients."

    drafts_block = "\n\n".join(
        "**Offer to " + str(c["n"]) + ". " + str(c.get("name") or "") + ":**\n\n" + "\n".join("> " + ln for ln in str(c["offer_text"]).split("\n"))
        for c in offers
    )
    recommended_ns = [str(c["n"]) for c in offers if c["recommended"]]

    description = (
        "**Free slot:** " + slot_label + " - " + end_label + (" · " + type_name if type_name else "") + "\n\n"
        + "**Why it's free:** " + ("a booking was cancelled" if slot.get("source") == "cancelled" else "a patient moved their booking to another time") + "\n\n"
        + "**Candidates (ranked):**\n\n" + candidate_block + "\n\n"
        + ("**Recommended to offer:** " + ", ".join(recommended_ns) + "\n\n" if recommended_ns else "")
        + ("**Drafted offers:**\n\n" + drafts_block + "\n\n" if offers else "")
        + ("_AI ranking failed (" + ai_problem[:200] + "); showing list order and a standard offer._\n\n" if ai_problem else "")
        + "Nothing has been sent yet. Use the form to choose who gets the offer, or close this item to leave the slot free."
    )

    # Same single-practice test assignee as the reschedule desk.
    PRACTITIONER_EMAIL = "sean.baker@mysmb.com"
    assignee_ids: list[str] = []
    try:
        for user in api.users.list() or []:
            if (user.get("email") or "").strip().lower() == PRACTITIONER_EMAIL:
                if user.get("id"):
                    assignee_ids = [str(user.get("id"))]
                break
    except Exception:
        assignee_ids = []

    try:
        hours_away = (parse(str(slot.get("starts_at") or "")) - now).total_seconds() / 3600
    except Exception:
        hours_away = 999
    item = api.workq.create(
        title=title,
        scope="org",
        description=description,
        priority="high" if hours_away < 24 else "medium",
        labels=["cliniko-automations", "gap-filler"],
        assignee_ids=assignee_ids or None,
    )
    todo_id = item["id"]
    # Step 4: the manager picks who gets the offer. Only worth asking when
    # there's someone who can actually be emailed.
    if offers:
        api.workq.attach_form(todo_id=todo_id, form_id=params["offer_form"])

    # Everything the offer-sending step needs once the form is submitted. Flat
    # filename to respect Knowledge's 2-level folder nesting limit.
    write_json(
        "PracticeManager/State/" + slug + "-gap-slot-" + todo_id + ".json",
        {"slot": slot, "slot_label": slot_label, "end_label": end_label, "appointment_type_name": type_name,
         "candidates": candidates, "offers": offers, "recommended": recommended_ns,
         "created_at": zulu(now)},
    )

    # Audit trail (healthcare-practice-management-guardrail-audit format).
    try:
        from zoneinfo import ZoneInfo
        today_str = now.astimezone(ZoneInfo(tz_name)).date().isoformat()
    except Exception:
        today_str = now.date().isoformat()
    audit_path = "PracticeManager/AuditLog/" + slug + "-" + today_str + ".jsonl"
    try:
        existing_log = api.files.read(file=audit_path, scope="org")
    except Exception:
        existing_log = ""
    audit_line = json.dumps({
        "ts": zulu(now),
        "practice_slug": slug,
        "actor": "agent",
        "source": "automation:Cliniko Automations: Find freed slots to fill",
        "action": "drafted",
        "target": {"kind": "appointment_slot", "id": str(slot.get("key") or "")},
        "summary": "Freed slot " + slot_label + ": " + str(len(offers)) + " offer(s) drafted for approval",
        "guardrails": [{"rule": "patient_facing_requires_approval", "result": "pass", "detail": "offers drafted only; routed to WorkQ for approval"}],
        "workq_item_id": todo_id,
    }, sort_keys=True)
    try:
        api.files.put(file=audit_path, content=existing_log + audit_line + "\n", scope="org")
    except Exception:
        pass

# Mark this slot handled only now that its WorkQ item exists (or one was
# already open). "Remember which slots were handled" merges this file with
# the run's other handled keys rather than overwriting it.
if todo_id or already_open:
    state_path = "PracticeManager/State/" + slug + "-gap-filler.json"
    try:
